119	            });
120	          document
121	            .querySelector<HTMLElement>(MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR)
122	            ?.setAttribute("data-active", "true");
123	          TextReveal.setVisibleOn(MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR);
124	          document
125	            .querySelector<HTMLElement>(MAIN_DEBUG_CONTACT_HEAD_SELECTOR)
126	            ?.setAttribute("data-active", "true");
