197	      await this._dependencies.startPageTheatreIntro(engine);
198	      Panel.getInstance().setVisibleOn();
199	      await this._playAboutHeroIntroDomReveal();
200	      await this._dependencies.syncAboutSceneState(pageConfig, "heroIntro", 1);
201	      if (ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED) {
202	        await this._dependencies.startPageTheatreAfterIntro(engine);
203	        await this._dependencies.syncAboutSceneState(pageConfig, "heroSlogan", 1);
204	      }
205	      this._finishAboutIntro(pageConfig, releaseAboutScrollLock);
206	      releaseAboutScrollLock = null;
207	      await this._dependencies.startPagePreviewIfNeeded();
208	    } finally {
209	      releaseAboutScrollLock?.();
210	      introRunner.dispose();
211	    }
212	  }
213	
214	  async runContactIntro(
215	    pageConfig: ContactPageConfig,
216	    objectSetupPromise: Promise<void>,
217	  ): Promise<void> {
