220	      objectSetupPromise,
221	      { deferScrollSync: true },
222	    );
223	
224	    const engine = this._dependencies.getEngine();
225	    if (!engine) {
226	      this._dependencies.syncContactDomState(null);
227	      return;
228	    }
229	
230	    await this._dependencies.runContactIntroSequence(engine);
231	    Panel.getInstance().setVisibleOff();
232	    HudPanel.getInstance().setVisibleOff();
233	    ScrollLock.unlock();
234	  }
