236	  private async _transitionMainIntroToHero(
237	    pageConfig: MainPageConfig,
238	  ): Promise<void> {
239	    this._dependencies.onMainIntroTransitionStateChange(true);
240	    try {
241	      this._dependencies.introHandoffRuntime.setHeroTextVisible(false);
242	      this._dependencies.dom.setHeroHandoffVisible(false);
243	      await this._dependencies.introHandoffRuntime.transitionToHero({
244	        gsap: this._dependencies.getGsap(),
245	        transitionRuntime: this._dependencies.sceneTransitionRuntime,
246	        veil: this._dependencies.resolveTransitionVeil(sceneTransitionVeil),
247	        steps: [
248	          SCENE_TRANSITION_VEIL_SEQUENCE.cover,
249	          SCENE_TRANSITION_VEIL_SEQUENCE.reveal,
250	        ],
251	        inactiveProgress: SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
252	        actionContentSelector: INTRO_ACTION_CONTENT_SELECTOR,
253	        actionContentOffsetY: INTRO_ACTION_TO_HERO_OFFSET_Y,
254	        actionContentDuration: INTRO_ACTION_TO_HERO_DURATION,
255	        onCoverComplete: async () => {
256	          this._dependencies
257	            .getEngine()
258	            ?.getBackgroundManager()
259	            ?.startTransition(mainBackground);
260	          await this._dependencies.syncMainSceneState(pageConfig, "hero", 0);
261	        },
262	      });
263	      this._dependencies.dom.setHeroHandoffVisible(true);
264	      await this._dependencies.introHandoffRuntime.playHeroTextRise();
265	      this._finishMainIntro(pageConfig);
266	    } finally {
267	      this._dependencies.onMainIntroTransitionStateChange(false);
268	    }
269	  }
270	
271	  private _finishMainIntro(pageConfig: MainPageConfig): void {
272	    HudPanel.getInstance().setVisibleOn();
273	    Panel.getInstance().setVisibleOff();
274	    window.scrollTo({ top: 0, behavior: "auto" });
275	    this._dependencies.introFlowRuntime.releaseScrollLock();
276	    this._dependencies.startMainScrollSyncAfterIntro(pageConfig);
277	  }
278	
279	  private _finishAboutIntro(
280	    pageConfig: AboutPageConfig,
281	    releaseScrollLock: (() => void) | null,
282	  ): void {
283	    HudPanel.getInstance().setVisibleOff();
284	    this._dependencies.startAboutScrollSyncAfterIntro(pageConfig);
285	    releaseScrollLock?.();
286	    window.requestAnimationFrame(() => {
287	      this._dependencies.dom.scrollToAboutSceneProgress(pageConfig, "heroIntro", 0);
288	    });
289	  }
290	
291	  private _resolveIntroOverlay(pageConfig: AppPageConfig): IntroConfig | null {
292	    return pageConfig.introOverlay ?? pageConfig.intro ?? null;
293	  }
294	
295	  private _prepareAboutHeroIntroDomReveal(): void {
296	    TextReveal.setVisibleOff(ABOUT_HERO_INTRO_TEXT_SELECTOR);
297	    BlockReveal.hide(ABOUT_HERO_INTRO_TOP_SELECTOR);
298	    BlockReveal.hide(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
299	  }
300	
301	  private async _playAboutHeroIntroDomReveal(): Promise<void> {
302	    BlockReveal.reveal(ABOUT_HERO_INTRO_TOP_SELECTOR);
303	    const textItems = Array.from(
304	      document.querySelectorAll<HTMLElement>(ABOUT_HERO_INTRO_TEXT_SELECTOR),
305	    );
306	    if (textItems.length > 0) {
307	      await new Promise<void>((resolve) => {
308	        let completed = 0;
309	        textItems.forEach((item, index) => {
310	          window.setTimeout(() => {
311	            TextReveal.riseUp(item);
312	            completed += 1;
313	            if (completed === textItems.length) {
314	              resolve();
315	            }
316	          }, index * ABOUT_HERO_INTRO_REVEAL_STAGGER_MS);
317	        });
318	      });
319	    }
320	    BlockReveal.reveal(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
321	    await new Promise<void>((resolve) => {
322	      window.setTimeout(resolve, ABOUT_HERO_INTRO_REVEAL_STAGGER_MS * 2);
323	    });
324	  }
325	}
