import * as THREE from "three";
import { SceneObject } from "../../core/SceneObject.js";
import type {
  BackgroundTweenProps,
} from "../../types/object.types.js";
import type { BackgroundObjectOptions } from "../../types/object-visual.types.js";
import type {
  BackgroundManagerRuntimePort,
  BackgroundRuntimePort,
  BackgroundRuntimeState,
} from "../../types/object-runtime.types.js";
import type { SceneSheetChangeEvent } from "../../types/runtime.types.js";

const BACKGROUND_MANAGER_RUNTIME_ID = "env.backgroundManager.runtime";

export class Background
  extends SceneObject<BackgroundTweenProps>
  implements BackgroundRuntimePort
{
  private readonly _backgroundId: string;
  private _options: Partial<BackgroundObjectOptions> = {};
  private _runtimeState: BackgroundRuntimeState = {};

  constructor(backgroundId: string) {
    super();
    this._backgroundId = backgroundId;
  }

  setOptions(props: Partial<BackgroundObjectOptions> | undefined): this {
    if (props) {
      this._options = {
        ...this._options,
        ...props,
        look: this._mergeLook(this._options.look, props.look),
      };
    }
    return this;
  }

  protected override getOptions(): Record<string, unknown> {
    return this._options;
  }

  override getRuntimeOptions(): Record<string, unknown> {
    this._syncOptionsFromRoot();
    return {
      ...this._options,
      exposure: this._runtimeState.exposure ?? this._options.exposure,
      look: this._mergeLook(this._options.look, this._runtimeState.look),
    };
  }

  protected override mergeOptionsFromTimeline(
    vars: Partial<BackgroundTweenProps>,
  ): void {
    if (Object.keys(vars).length === 0) return;
    this._options = {
      ...this._options,
      ...vars,
      look: this._mergeLook(this._options.look, vars.look),
    };
  }

  override getAnimationTarget(): THREE.Object3D | null {
    return this.getTimelineRoot();
  }

  override getBloomEnabled(): boolean {
    return false;
  }

  protected override applyVisibility(visible: boolean): void {
    const root = this.ensureTimelineRoot(this._backgroundId);
    if (!root) return;
    root.visible = visible;
    this._options.visible = visible;
    this._syncManagerOptions();
  }

  protected override syncFromOptions(): void {
    this._applyTransform();
    this._syncManagerOptions();
  }

  override async runObject(): Promise<void> {
    this.ensureTimelineRoot(this._backgroundId);
    this._applyTransform();
    this._registerManager();
    this._syncManagerOptions();
    this._syncManagerState();
  }

  override runUpdate(_delta: number): void {
    this._syncOptionsFromRoot();
    this._syncManagerOptions();
  }

  override dispose(): void {
    this._getManager()?.unregister(this._backgroundId);
    super.dispose();

