  for (let index = 0; index < positions.length; index += 1) {
    if (sheetPosition <= positions[index]) return index;
  }
  return null;
}

private _syncAfterIntroRestState(engine: Engine): void {
  this._syncSheetState(engine, "introAction", 0);
}

private _readIntroActionRestTarget(): MainTheatreValue["camera"]["target"] {
  return {
    ...this.readState("introAction", 0).camera.target,
  };
}

private _syncIntroActionEndState(engine: Engine, position: number): void {
  this._syncSheetState(engine, "introAction", position);
}

private _resolveIntroActionPhaseOneRange(): MainTheatrePlaybackRange {
  const baseRange = this._resolveCameraPlaybackRange(
    "introAction",
    this._lengthBySheetId.get("introAction") ?? 0,
  );
  return {
    start: baseRange.start,
    end: Math.min(baseRange.end, MAIN_INTRO_ACTION_PHASE_SPLIT_POSITION),
  };
}

private _resolveIntroActionPhaseTwoRange(): MainTheatrePlaybackRange {
  const baseRange = this._resolveCameraPlaybackRange(
    "introAction",
    this._lengthBySheetId.get("introAction") ?? 0,
  );
  const start = Math.min(baseRange.end, MAIN_INTRO_ACTION_PHASE_SPLIT_POSITION);
  return {
    start,
    end: baseRange.end,
  };
}

private _startSheetAutoplayRange(
  engine: Engine,
  sheetId: MainTheatreSheetId,
  range: MainTheatrePlaybackRange,
  options: {
    rate: number;
    fallbackSync: (engine: Engine) => void;
    completeSync: (engine: Engine) => void;
    beforePlay?: () => void;
  },
): Promise<void> {
  return this._autoplayRuntime.startSheetAutoplay(engine, {
    sheetId,
    resolveBinding: this._resolveSheetBinding,
    resolveRange: () => range,
    rate: options.rate,
    fallbackSync: options.fallbackSync,
    completeSync: (targetEngine) => options.completeSync(targetEngine),
    beforePlay: options.beforePlay,
  });
}

private _syncSheetState(
  engine: Engine,
  sheetId: MainTheatreSheetId,
  position: number,
): void {
  const binding = this._resolveSheetBinding(sheetId);
  if (!binding) {
    this.syncSceneToEngine(engine, "hero", 0);
    return;
  }
  binding.sequence.pause();
  binding.sequence.position = position;
  this._applyState(engine, binding.object.value);
}

private _applyState(engine: Engine, values: MainTheatreValue): void {
  this._rig.apply(engine, mergeMainSceneState(values));
}

