varying float vSeed, vRatio;
varying vec2 vUv;
varying vec3 vNormal;
varying vec3 vViewDirection;

void main() {
    vec2 ratioedUv = vec2(5.0, vRatio) * (vUv + vSeed * 0.1);
    vec2 resizedUv = uSize * ratioedUv;
    vec2 sUv = gl_FragCoord.xy / max(uResolution, vec2(1.0));
    float mouse = clamp(texture2D(tMouse, sUv + 0.1 * (texture2D(tNoise, 0.4 * resizedUv).g - 0.5)).r, 0.0, 1.0);
    float time = uTime * 0.5 / max(uSize.x, 0.0001);
    float strength = 1.0;
    vec2 dUv = vUv;
    dUv *= 1.0 + 0.03 * mouse;
    dUv += 0.05 * mouse;
    dUv.y += 0.3 * strength * (texture2D(tNoise, resizedUv * 0.2 + vec2(-0.004, -0.02) * time).r - 0.5);
    dUv.y -= 0.5 * strength * (texture2D(tNoise, resizedUv * 0.08 + vec2(0.005, 0.01) * time).r - 0.5);
    dUv.y *= 1.0 + 0.1 * strength * (texture2D(tPerlin, resizedUv * 0.5 - 0.01 * time).r - 0.5);
    float smoothness = smoothstep(0.4, 0.7, texture2D(tNoise, resizedUv * 0.08 + vec2(-0.08, -0.04) * time).r);
    float clouds = smoothstep(0.9 - 0.1 * smoothness, 0.7, dUv.y);
    clouds *= smoothstep(0.0, 0.2, dUv.y - 0.2 * smoothstep(0.4, 1.0, dUv.x));
  float alpha = clouds * smoothstep(1.0, 0.9, vUv.y) * smoothstep(0.0, 0.1, vUv.y) * smoothstep(0.0, 0.1, vUv.x) * smoothstep(1.0, 0.9, vUv.x);
  alpha += smoothstep(0.2, 0.3, vUv.y) * smoothstep(0.7, 0.6, vUv.y) * smoothstep(0.2, 0.3, vUv.x) * smoothstep(0.9, 0.8, vUv.x);
  alpha = min(1.0, alpha);
  float borderFadeX =
    smoothstep(0.0, 0.22, vUv.x) *
    smoothstep(0.0, 0.22, 1.0 - vUv.x);
  float borderFadeY =
    smoothstep(0.0, 0.18, vUv.y) *
    smoothstep(0.0, 0.18, 1.0 - vUv.y);
  vec2 radialUv = (vUv - 0.5) * vec2(1.18, 0.86);
  float radialFade = 1.0 - smoothstep(0.56, 0.96, length(radialUv));
  alpha *= borderFadeX * borderFadeY;
  alpha *= max(radialFade, clouds * 0.72);

  vec2 rocketDelta = vUv - uRocketUv;
  float rocketDistance = length(rocketDelta);
  float rocketHole =
    (1.0 - smoothstep(uRocketRadius, uRocketRadius + 0.12, rocketDistance)) *
    clamp(uRocketInfluence, 0.0, 1.0);
  alpha *= 1.0 - rocketHole * 0.42;

  float cloudDarkness = smoothstep(0.4, 1.0, dUv.y) + smoothstep(0.4, 0.0, dUv.y);
  vec3 normalDirection = normalize(vNormal);
  vec3 viewDirection = normalize(vViewDirection);
    float rim = pow(1.0 - clamp(dot(normalDirection, viewDirection), 0.0, 1.0), 2.4);
    vec3 color = mix(uDarkColor, uLightColor, clamp(cloudDarkness, 0.0, 1.0));
    color += uLightColor * 0.04 * rim * alpha;
    color = mix(color, uDarkColor, rocketHole * 0.18);

    float whiteText = smoothstep(2.2, 2.3, uChapter);
    color *= mix(vec3(1.0), vec3(0.8, 0.85, 0.87), whiteText);
    vec2 guillotineUv = vec2(uRatio, 1.0) * 0.4 * sUv;
    float guillotine = smoothstep(2.3, 2.2, uChapter - 0.3 * sUv.y + 0.1 * (texture2D(tNoise, guillotineUv + 0.02 * texture2D(tNoise, 4.0 * guillotineUv).r).r - 0.5));
    alpha *= guillotine;
    alpha *= smoothstep(1.0, 0.3, uTransition);
    alpha *= smoothstep(0.6, 0.96, abs(vNormal.b));
    gl_FragColor = vec4(color, alpha * clamp(uOpacity, 0.0, 1.0));
}

import {
  pageAbout,
  mainBackground,
  sceneTransitionVeil,
} from "../core/setup.js";
import { ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED } from "../pages/about/theatre/AboutTheatreConfig.js";
import { EnvSetup } from "../app/EnvSetup.js";
import { ScrollLock } from "../utils/ScrollLock.js";
import { HudPanel } from "../ui/HudPanel.js";
import { Panel } from "../ui/Panel.js";
import { IntroOverlay } from "../ui/IntroOverlay.js";
import { TextReveal } from "../animation/TextReveal.js";
import { BlockReveal } from "../animation/BlockReveal.js";
import { DOM_CONFIG } from "../config/dom.config.js";
import { SCENE_TRANSITION_VEIL_SEQUENCE } from "../config/transition.config.js";
import type { GsapGlobal } from "../types/gsap.types.js";
import type {
  AboutPageConfig,
  AboutSceneSectionKey,
} from "../types/about.types.js";
import type { ContactPageConfig } from "../types/contact.types.js";
import type {
  MainPageConfig,
  MainSceneSectionKey,
} from "../types/main.types.js";
import type { AppPageConfig } from "../types/runtime.types.js";
import type { IntroConfig } from "../types/core.types.js";
import type { IntroControllerDependencies } from "../types/intro.types.js";

const MAIN_FLOW = DOM_CONFIG.keys.mainFlow;
const INTRO_ACTION_CONTENT_SELECTOR =
  MAIN_FLOW?.introActionContent ?? ".no-main-intro-action__content";
const INTRO_ACTION_TO_HERO_DURATION = 1.18;
const INTRO_ACTION_TO_HERO_OFFSET_Y = -32;
const ABOUT_HERO_INTRO_TEXT_SELECTOR =
  ".no-sub-about-hero-intro .mask-target";
const ABOUT_HERO_INTRO_TOP_SELECTOR =
  ".no-sub-about-hero-intro__top.is-block-reveal";
const ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR =
  ".no-sub-about-hero-intro__desc.is-block-reveal, .no-sub-about-hero-intro__info.is-block-reveal";
const ABOUT_HERO_INTRO_REVEAL_STAGGER_MS = 140;
const MAIN_DEBUG_WHO_TEXT_SELECTOR = ".no-main-who .mask-target";
const MAIN_DEBUG_WHY_TEXT_SELECTOR = ".no-main-why .mask-target";
const MAIN_DEBUG_WHY_BODY_SELECTOR = ".no-main-why__body";
const MAIN_DEBUG_WHY_VISUAL_SELECTOR = ".no-main-why__visual";
const MAIN_DEBUG_WHY_CARD_SELECTOR = ".no-main-why__card";
const MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR = ".no-main-portfolio__head";
const MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR = ".no-main-portfolio__head .mask-target";
const MAIN_DEBUG_CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
const MAIN_DEBUG_CONTACT_TEXT_SELECTOR = ".no-main-contact .mask-target";

export class IntroController {
  private readonly _dependencies: IntroControllerDependencies;

  constructor(dependencies: IntroControllerDependencies) {
    this._dependencies = dependencies;
  }

  hasIntro(pageConfig: AppPageConfig, gsap: GsapGlobal | null): boolean {
    return !!this._resolveIntroOverlay(pageConfig)?.tl && !!gsap;
  }

  async runMainIntro(
    pageConfig: MainPageConfig,
    objectSetupPromise: Promise<void>,
    gsap: GsapGlobal,
  ): Promise<void> {
    const introConfig = this._resolveIntroOverlay(pageConfig);
    if (!introConfig) return;
    const isDebugMode = EnvSetup.hasQueryFlag("debug", "1");

    await this._dependencies.introFlowRuntime.run({
      introConfig,
      gsap,
      loadPromise: this._dependencies.runAfterLoad(
        pageConfig,
        objectSetupPromise,
        { deferScrollSync: true },
      ),
      root: this._dependencies.getRoot(),
      disableScrollLock: isDebugMode,
      showDebugDomState: isDebugMode,
      keepIntroActionVisible: isDebugMode,
      onAfterIntroAutoplay: isDebugMode
        ? undefined
        : async () => {
            const engine = this._dependencies.getEngine();
            if (!engine) return;
            await this._dependencies.startPageTheatreAfterIntro(engine);
          },
      onIntroDomRevealComplete: () => {
        this._dependencies.onMainIntroDomRevealComplete();
        if (isDebugMode) {
          this._dependencies.dom.setHeroHandoffVisible(true);
          TextReveal.setVisibleOn(MAIN_DEBUG_WHO_TEXT_SELECTOR);
          TextReveal.setVisibleOn(MAIN_DEBUG_WHY_TEXT_SELECTOR);
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
            ?.style.setProperty("opacity", "1");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
            ?.style.setProperty("visibility", "visible");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_BODY_SELECTOR)
            ?.style.setProperty("transform", "translate3d(-50%, -50%, 0)");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
            ?.style.setProperty("opacity", "1");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
            ?.style.setProperty("visibility", "visible");
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WHY_VISUAL_SELECTOR)
            ?.style.setProperty("transform", "translate3d(-50%, -50%, 0)");
          document
            .querySelectorAll<HTMLElement>(MAIN_DEBUG_WHY_CARD_SELECTOR)
            .forEach((card) => {
              card.style.setProperty("--card-opacity", "1");
            });
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_WORKS_DETAIL_HEAD_SELECTOR)
            ?.setAttribute("data-active", "true");
          TextReveal.setVisibleOn(MAIN_DEBUG_WORKS_DETAIL_TEXT_SELECTOR);
          document
            .querySelector<HTMLElement>(MAIN_DEBUG_CONTACT_HEAD_SELECTOR)
            ?.setAttribute("data-active", "true");
          TextReveal.setVisibleOn(MAIN_DEBUG_CONTACT_TEXT_SELECTOR);
        }
      },
          onIntroActionAutoplay: isDebugMode
        ? undefined
        : async () => {
            const engine = this._dependencies.getEngine();
            if (!engine) return;
            const hudPanel = HudPanel.getInstance();
            hudPanel.setVisibleOn();
            hudPanel.setIntroActionFlightEnabled(false);
            this._dependencies.syncMainIntroBackground(pageConfig, "introAction", 1);
            await this._dependencies.startMainIntroActionPhaseOne(engine);
            const wasSkipped =
              await this._dependencies.introFlowRuntime.playIntroActionCountdown(
                this._dependencies.getGsap(),
              );
            if (wasSkipped) {
              hudPanel.setIntroActionFlightEnabled(false);
              hudPanel.syncFlightProgress("hero", 0, "hero");
              return;
            }
            hudPanel.startIntroActionFlight();
            await Promise.all([
              this._dependencies.startMainIntroActionPhaseTwo(engine),
              this._dependencies.introFlowRuntime.playIntroActionStorySequence(
                this._dependencies.getGsap(),
              ),
            ]);
          },
      onIntroActionTransition: isDebugMode
        ? undefined
        : async () => {
            await this._transitionMainIntroToHero(pageConfig);
          },
      onPreviewStart: isDebugMode
        ? undefined
        : this._dependencies.startPagePreviewIfNeeded,
    });
  }

  async runAboutIntro(
    pageConfig: AboutPageConfig,
    objectSetupPromise: Promise<void>,
    gsap: GsapGlobal,
  ): Promise<void> {
    const introConfig = this._resolveIntroOverlay(pageConfig);
    if (!introConfig) return;

    this._dependencies.dom.setAboutScenePlanesVisible(pageConfig, false);
    this._dependencies.dom.setAboutUiPhase("intro");

    const introRunner = new IntroOverlay(introConfig);
    let releaseAboutScrollLock: (() => void) | null = null;
    try {
      await introRunner.run({
        gsap,
        loadPromise: this._dependencies.runAfterLoad(
          pageConfig,
          objectSetupPromise,
          { deferScrollSync: true },
        ),
      });

      const engine = this._dependencies.getEngine();
      if (!engine) return;

      releaseAboutScrollLock = ScrollLock.lock({ pauseLenis: true });
      this._prepareAboutHeroIntroDomReveal();
      await this._dependencies.dom.revealAboutScenePlanes(pageConfig, gsap);
      await this._dependencies.startPageTheatreIntro(engine);
      Panel.getInstance().setVisibleOn();
      await this._playAboutHeroIntroDomReveal();
      await this._dependencies.syncAboutSceneState(pageConfig, "heroIntro", 1);
      if (ABOUT_AFTER_INTRO_AUTOPLAY_ENABLED) {
        await this._dependencies.startPageTheatreAfterIntro(engine);
        await this._dependencies.syncAboutSceneState(pageConfig, "heroSlogan", 1);
      }
      this._finishAboutIntro(pageConfig, releaseAboutScrollLock);
      releaseAboutScrollLock = null;
      await this._dependencies.startPagePreviewIfNeeded();
    } finally {
      releaseAboutScrollLock?.();
      introRunner.dispose();
    }
  }

  async runContactIntro(
    pageConfig: ContactPageConfig,
    objectSetupPromise: Promise<void>,
  ): Promise<void> {
    await this._dependencies.runAfterLoad(
      pageConfig,
      objectSetupPromise,
      { deferScrollSync: true },
    );

    const engine = this._dependencies.getEngine();
    if (!engine) {
      this._dependencies.syncContactDomState(null);
      return;
    }

    await this._dependencies.runContactIntroSequence(engine);
    Panel.getInstance().setVisibleOff();
    HudPanel.getInstance().setVisibleOff();
    ScrollLock.unlock();
  }

  private async _transitionMainIntroToHero(
    pageConfig: MainPageConfig,
  ): Promise<void> {
    this._dependencies.onMainIntroTransitionStateChange(true);
    try {
      this._dependencies.introHandoffRuntime.setHeroTextVisible(false);
      this._dependencies.dom.setHeroHandoffVisible(false);
      await this._dependencies.introHandoffRuntime.transitionToHero({
        gsap: this._dependencies.getGsap(),
        transitionRuntime: this._dependencies.sceneTransitionRuntime,
        veil: this._dependencies.resolveTransitionVeil(sceneTransitionVeil),
        steps: [
          SCENE_TRANSITION_VEIL_SEQUENCE.cover,
          SCENE_TRANSITION_VEIL_SEQUENCE.reveal,
        ],
        inactiveProgress: SCENE_TRANSITION_VEIL_SEQUENCE.inactiveProgress,
        actionContentSelector: INTRO_ACTION_CONTENT_SELECTOR,
        actionContentOffsetY: INTRO_ACTION_TO_HERO_OFFSET_Y,
        actionContentDuration: INTRO_ACTION_TO_HERO_DURATION,
        onCoverComplete: async () => {
          this._dependencies
            .getEngine()
            ?.getBackgroundManager()
            ?.startTransition(mainBackground);
          await this._dependencies.syncMainSceneState(pageConfig, "hero", 0);
        },
      });
      this._dependencies.dom.setHeroHandoffVisible(true);
      await this._dependencies.introHandoffRuntime.playHeroTextRise();
      this._finishMainIntro(pageConfig);
    } finally {
      this._dependencies.onMainIntroTransitionStateChange(false);
    }
  }

  private _finishMainIntro(pageConfig: MainPageConfig): void {
    HudPanel.getInstance().setVisibleOn();
    Panel.getInstance().setVisibleOff();
    window.scrollTo({ top: 0, behavior: "auto" });
    this._dependencies.introFlowRuntime.releaseScrollLock();
    this._dependencies.startMainScrollSyncAfterIntro(pageConfig);
  }

  private _finishAboutIntro(
    pageConfig: AboutPageConfig,
    releaseScrollLock: (() => void) | null,
  ): void {
    HudPanel.getInstance().setVisibleOff();
    this._dependencies.startAboutScrollSyncAfterIntro(pageConfig);
    releaseScrollLock?.();
    window.requestAnimationFrame(() => {
      this._dependencies.dom.scrollToAboutSceneProgress(pageConfig, "heroIntro", 0);
    });
  }

  private _resolveIntroOverlay(pageConfig: AppPageConfig): IntroConfig | null {
    return pageConfig.introOverlay ?? pageConfig.intro ?? null;
  }

  private _prepareAboutHeroIntroDomReveal(): void {
    TextReveal.setVisibleOff(ABOUT_HERO_INTRO_TEXT_SELECTOR);
    BlockReveal.hide(ABOUT_HERO_INTRO_TOP_SELECTOR);
    BlockReveal.hide(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
  }

  private async _playAboutHeroIntroDomReveal(): Promise<void> {
    BlockReveal.reveal(ABOUT_HERO_INTRO_TOP_SELECTOR);
    const textItems = Array.from(
      document.querySelectorAll<HTMLElement>(ABOUT_HERO_INTRO_TEXT_SELECTOR),
    );
    if (textItems.length > 0) {
      await new Promise<void>((resolve) => {
        let completed = 0;
        textItems.forEach((item, index) => {
          window.setTimeout(() => {
            TextReveal.riseUp(item);
            completed += 1;
            if (completed === textItems.length) {
              resolve();
            }
          }, index * ABOUT_HERO_INTRO_REVEAL_STAGGER_MS);
        });
      });
    }
    BlockReveal.reveal(ABOUT_HERO_INTRO_BOTTOM_BLOCK_SELECTOR);
    await new Promise<void>((resolve) => {
      window.setTimeout(resolve, ABOUT_HERO_INTRO_REVEAL_STAGGER_MS * 2);
    });
  }
}

import { Rocket } from "../objects/rocket/Rocket.js";
import { JetEngine } from "../objects/rocket/JetEngine.js";
import { GravityBalls } from "../objects/main/GravityBalls.js";
import { Background } from "../objects/env/Background.js";
import { CloudPlane } from "../objects/env/CloudPlane.js";
import { Ground } from "../objects/main/Ground.js";
import { Light } from "../objects/env/SceneLights.js";
import { Earth } from "../objects/shared/Earth.js";
import { Planet } from "../objects/shared/Planet.js";
import { Astronaut } from "../objects/sub/Astronaut.js";
import { AboutTerrian } from "../objects/sub/AboutTerrian.js";
import { TransitionVeil } from "../objects/sub/TransitionVeil.js";
import { Window } from "../objects/main/Window.js";
import type { Engine } from "../core/Engine.js";
import type { SceneObject } from "../core/SceneObject.js";
import type { PageConfig } from "../types/core.types.js";
import {
  rocket,
  jetEngine,
  gravityBalls,
  mainBackground,
  aboutBackground,
  cloud,
  cloud2,
  cloud3,
  cloud4,
  cloud5,
  cloud6,
  ground,
  planet,
  sceneLights,
  earth,
  astronaut,
  sceneTransitionVeil,
  terrian,
  windowObj,
} from "../core/setup.js";
import type {
  SceneLightsObjectOptions,
  ObjectOptionsByKey,
} from "../types/object.types.js";
import type {
  ObjectFactoryRegistry,
  ObjectRegistrationSpec,
  ISetup,
} from "../types/runtime.types.js";
import { ObjectConfigRuntime } from "../runtime/ObjectConfigRuntime.js";

function createSetOptionsSpec(
  id: keyof ObjectOptionsByKey,
  create: () => SceneObject,
): ObjectRegistrationSpec {
  return {
    id,
    create,
    applyOptions: (instance, options) => {
      const target = instance as { setOptions?: (props: unknown) => unknown };
      if (typeof target.setOptions === "function") {
        target.setOptions(options);
      }
    },
  };
}

function createDefaultRegistry(): ObjectFactoryRegistry {
  return {
    [rocket]: createSetOptionsSpec(rocket, () => new Rocket()),
    [jetEngine]: createSetOptionsSpec(jetEngine, () => new JetEngine()),
    [gravityBalls]: createSetOptionsSpec(gravityBalls, () => new GravityBalls()),
    [mainBackground]: createSetOptionsSpec(
      mainBackground,
      () => new Background(mainBackground),
    ),
    [aboutBackground]: createSetOptionsSpec(
      aboutBackground,
      () => new Background(aboutBackground),
    ),
    [cloud]: createSetOptionsSpec(
      cloud,
      () => new CloudPlane(),
    ),
    [cloud2]: createSetOptionsSpec(
      cloud2,
      () => new CloudPlane(),
    ),
    [cloud3]: createSetOptionsSpec(
      cloud3,
      () => new CloudPlane(),
    ),
    [cloud4]: createSetOptionsSpec(
      cloud4,
      () => new CloudPlane(),
    ),
    [cloud5]: createSetOptionsSpec(
      cloud5,
      () => new CloudPlane(),
    ),
    [cloud6]: createSetOptionsSpec(
      cloud6,
      () => new CloudPlane(),
    ),
    [ground]: createSetOptionsSpec(ground, () => new Ground()),
    [planet]: createSetOptionsSpec(planet, () => new Planet()),
    [sceneLights]: {
      id: sceneLights,
      create: () => new Light(),
      applyOptions: (instance, options) => {
        const target = instance as {
          setOptions?: (
            props: Partial<SceneLightsObjectOptions> | undefined,
          ) => unknown;
        };
        target.setOptions?.(
          options as Partial<SceneLightsObjectOptions> | undefined,
        );
      },
    },
    [earth]: createSetOptionsSpec(earth, () => new Earth()),
    [astronaut]: createSetOptionsSpec(astronaut, () => new Astronaut()),
    [sceneTransitionVeil]: createSetOptionsSpec(
      sceneTransitionVeil,
      () => new TransitionVeil(),
    ),
    [terrian]: createSetOptionsSpec(terrian, () => new AboutTerrian()),
    [windowObj]: createSetOptionsSpec(windowObj, () => new Window()),
  };
}

export class ObjectSetup implements ISetup<
  [Engine, PageConfig],
  Promise<void>
> {
  private readonly _registry = new Map<string, ObjectRegistrationSpec>();
  private readonly _configRuntime = new ObjectConfigRuntime();
  private _disposed = false;
  private static readonly _ENV_ALIAS_BY_OBJECT_ID: Readonly<
    Partial<Record<keyof ObjectOptionsByKey, string>>
  > = {
    [sceneLights]: "env.light",
  };

  constructor(registry: ObjectFactoryRegistry = createDefaultRegistry()) {
    for (const [id, spec] of Object.entries(registry)) {
      this._registry.set(id, spec);
    }
  }

  registerFactory(id: string, spec: ObjectRegistrationSpec): void {
    this._registry.set(id, spec);
  }

  register(id: string, spec: ObjectRegistrationSpec): void {
    this.registerFactory(id, spec);
  }

  async init(engine: Engine, pageConfig: PageConfig): Promise<void> {
    if (this._disposed) return;
    for (const [id, spec] of this._getEnabledSpecs(pageConfig)) {
      const object = this._createConfiguredObject(
        spec,
        pageConfig.objectOptions,
        pageConfig.initialState,
      );
      await engine.setObject(id, object);
      this._registerEnvironmentAlias(engine, id as keyof ObjectOptionsByKey);
    }
  }

  dispose(): void {
    if (this._disposed) return;
    this._disposed = true;
    this._registry.clear();
  }

  private _getEnabledSpecs(
    pageConfig: PageConfig,
  ): Array<[string, ObjectRegistrationSpec]> {
    const enabledSpecs: Array<[string, ObjectRegistrationSpec]> = [];
    for (const [id, enabled] of Object.entries(pageConfig.objects)) {
      if (!enabled) continue;
      const spec = this._registry.get(id);
      if (!spec) continue;
      enabledSpecs.push([id, spec]);
    }
    return enabledSpecs;
  }

  private _createConfiguredObject(
    spec: ObjectRegistrationSpec,
    pageOptions: PageConfig["objectOptions"] | undefined,
    initialState: PageConfig["initialState"] | undefined,
  ): SceneObject {
    const object = spec.create();
    const resolvedConfig = this._configRuntime.resolve(
      spec.id,
      pageOptions,
      initialState,
    );
    spec.applyOptions?.(object, resolvedConfig.options);
    if (resolvedConfig.effects && typeof object.setEffects === "function") {
      object.setEffects(resolvedConfig.effects);
    }
    return object;
  }

  private _registerEnvironmentAlias(
    engine: Engine,
    objectId: keyof ObjectOptionsByKey,
  ): void {
    const envAlias = ObjectSetup._ENV_ALIAS_BY_OBJECT_ID[objectId];
    if (!envAlias) return;
    const target = engine.getObjectById(objectId as string);
    if (!target || typeof target !== "object") return;
    engine
      .getScene()
      .registerObject(envAlias, target as Record<string, unknown>);
  }
}

