import * as TheatreCore from "@theatre/core";
import type {
  TheatreObjectPort,
  TheatreSequencePort,
} from "../../types/theatre.types.js";

const theatreCoreApi = TheatreCore.default;

export class TheatrePlaybackService {
  static bindValues<TValue, TProps>(
    object: TheatreObjectPort<TValue, TProps>,
    callback: (values: TValue) => void,
  ): () => void {
    return object.onValuesChange(callback);
  }

  static bindPlaying(
    sequence: TheatreSequencePort,
    callback: (playing: boolean) => void,
  ): () => void {
    return theatreCoreApi.onChange(
      sequence.pointer.playing as never,
      (playing) => {
      callback(playing === true);
      },
    );
  }
}

