import * as THREE from "three";
import type { SceneObject } from "../core/SceneObject.js";
import type { SceneObjectContext } from "../types/engine.types.js";

export class Scene {
  readonly three: THREE.Scene;
  private _objects = new Map<string, SceneObject>();

  private _rawObjects = new Map<string, THREE.Object3D | Record<string, unknown>>();
  private _objectRegisteredListeners = new Set<(id: string) => void>();
  private _context: SceneObjectContext | null = null;
  constructor() {
    this.three = new THREE.Scene();
  }

  setContext(context: SceneObjectContext): void {
    this._context = context;
  }

  get context(): SceneObjectContext | null {
    return this._context;
  }

  async addObject(id: string, object: SceneObject): Promise<void> {
    if (!this._context) return;
    this._objects.set(id, object);
    object.init(this._context);
    const runResult = object.runObject();
    if (runResult && runResult instanceof Promise) await runResult;
    this._emitObjectRegistered(id);
  }


  registerObject(id: string, obj: THREE.Object3D | Record<string, unknown>): void {
    this._rawObjects.set(id, obj);
    this._emitObjectRegistered(id);
  }

  unregisterObject(id: string): void {
    this._rawObjects.delete(id);
  }

  onObjectRegistered(listener: (id: string) => void): () => void {
    this._objectRegisteredListeners.add(listener);
    return () => {
      this._objectRegisteredListeners.delete(listener);
    };
  }


  getObject(id: string): THREE.Object3D | Record<string, unknown> | null {
    return this._rawObjects.get(id)
      ?? this._objects.get(id)?.getAnimationTarget()
      ?? null;
  }

  getSceneObject(id: string): SceneObject | null {
    return this._objects.get(id) ?? null;
  }

  removeObject(id: string): void {
    const object = this._objects.get(id);
    if (!object) return;
    object.dispose();
    this._objects.delete(id);
  }

  getObjectIds(): string[] {
    return [
      ...this._objects.keys(),
      ...this._rawObjects.keys(),
    ];
  }


  getAll(): Record<string, SceneObject> {
    return Object.fromEntries(this._objects);
  }

  private _bloomRootsCache = new Set<THREE.Object3D>();

  getBloomRoots(): Set<THREE.Object3D> {
    const roots = this._bloomRootsCache;
    roots.clear();
    for (const obj of this._objects.values()) {
      if (obj.isDisposed || !obj.getVisibleState() || !obj.getBloomEnabled()) continue;
      const target = obj.getBloomTarget();
      if (target && target.parent) roots.add(target);
    }
    return roots;
  }

  update(deltaTime: number): void {
    for (const obj of this._objects.values()) {
      if (!obj.isDisposed) obj.runUpdate(deltaTime);
    }
  }

  dispose(): void {
    for (const obj of this._objects.values()) {
      obj.dispose();
    }
    this._objects.clear();
    this._rawObjects.clear();
    this._objectRegisteredListeners.clear();
    this.three.traverse((child) => {
      if (!(child instanceof THREE.Mesh)) return;
      child.geometry?.dispose();
      const mats = Array.isArray(child.material)
        ? child.material
        : [child.material];
      for (const material of mats) {
        material?.dispose();
      }
    });
    this._context = null;
  }

  private _emitObjectRegistered(id: string): void {
    for (const listener of this._objectRegisteredListeners) {
      try {
        listener(id);
      } catch (error) {
        console.warn("[Scene._emitObjectRegistered] Listener failed.", error);
      }
    }
  }
}

