syncSceneToEngine(
  engine: Engine,
  sceneKey: MainSceneSectionKey,
  progress: number,
): MainSceneProgressState | null {
  const resolvedState = this.resolveSceneState(sceneKey, progress);
  this._rig.apply(
    engine,
    mergeMainSceneState(resolvedState ?? DEFAULT_MAIN_SCENE_STATE),
  );
  return this.resolveSceneProgressState(sceneKey, progress);
}

readState(sheetId: MainTheatreSheetId, position = 0): MainTheatreValue {
  const sequence = this._sequenceBySheetId.get(sheetId);
  const object = this._objectBySheetId.get(sheetId);
  if (!sequence || !object) return mergeMainSceneState();
  const previousPosition = sequence.position;
  sequence.position = this._clampPosition(
    position,
    this._lengthBySheetId.get(sheetId) ?? 0,
  );
  const state = mergeMainSceneState(object.value);
  sequence.position = previousPosition;
  return state;
}

readPlaybackRange(sheetId: MainTheatreSheetId): MainTheatrePlaybackRange {
  const length = this._lengthBySheetId.get(sheetId) ?? 0;
  return this._resolvePlaybackRange(sheetId, length);
}

readCameraPlaybackRange(
  sheetId: MainTheatreSheetId,
): MainTheatrePlaybackRange {
  const length = this._lengthBySheetId.get(sheetId) ?? 0;
  return this._resolveCameraPlaybackRange(sheetId, length);
}

resolveSceneProgressState(
  sceneKey: MainSceneSectionKey,
  progress: number,
): MainSceneProgressState | null {
  const resolvedSteps = this._resolveSceneSteps(sceneKey)
    .map((step) => this._resolveStep(step))
    .filter((step): step is MainResolvedTheatrePlaybackStep => step != null);
  if (resolvedSteps.length === 0) return null;
  const clampedProgress = this._clampPosition(progress, 1);
  for (const step of resolvedSteps) {
    if (!this._isProgressWithinRange(clampedProgress, step.progressRange)) {
      continue;
    }
    const localProgress = this._resolveLocalProgress(
      clampedProgress,
      step.progressRange,
    );
    return {
      sheetId: step.sheetId,
      localProgress,
    };
  }
  return null;
}

